// Tells if a line extends C.
bool nc_extension_line(NcLayoutLine line) {
    size_t i = 0;
    while (i < line.ts.n && line.ts.v[i].kind == NC_SPACE) {
        ++i;
    }
    if (i == line.ts.n || !nc_is(line.ts.v[i++], "@")) {
        return 0;
    }
    while (i < line.ts.n && line.ts.v[i].kind == NC_SPACE) {
        ++i;
    }
    return i < line.ts.n && line.ts.v[i].kind == NC_WORD;
}

// Tells if a line is meta.

bool nc_meta_line(NcLayoutLine line) {
    size_t i = 0;
    while (i < line.ts.n && line.ts.v[i].kind == NC_SPACE) {
        ++i;
    }
    if (i == line.ts.n || !nc_is(line.ts.v[i++], "@")) {
        return 0;
    }
    while (i < line.ts.n && line.ts.v[i].kind == NC_SPACE) {
        ++i;
    }
    if (i == line.ts.n) {
        return 0;
    }
    NcToken t = line.ts.v[i];
    return nc_is(t, "ct") || nc_is(t, "bt") || nc_is(t, "m") || nc_is(t, "macro");
}

